     1	/* Smoke test: runs the real openchair binary (path in OPENCHAIR_BIN) and
     2	 * checks its output and exit status, plus a direct library call. */
     3	#define _POSIX_C_SOURCE 200809L
     4	
     5	#include <errno.h>
     6	#include <stdio.h>
     7	#include <string.h>
     8	#include <sys/wait.h>
     9	#include <unistd.h>
    10	
    11	#include "openchair_version.h"
    12	
    13	#ifndef OPENCHAIR_BIN
    14	#error "OPENCHAIR_BIN must be defined"
    15	#endif
    16	
    17	static int failures;
    18	
    19	#define CHECK(cond)                                                        \
    20	    do {                                                                   \
    21	        if (!(cond)) {                                                     \
    22	            fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
    23	            failures++;                                                    \
    24	        }                                                                  \
    25	    } while (0)
    26	
    27	struct result {
    28	    int status;      /* exit code, or -1 on abnormal termination/error */
    29	    char out[512];
    30	    char err[512];
    31	};
    32	
    33	static ssize_t drain(int fd, char *buf, size_t cap)
    34	{
    35	    size_t len = 0;
    36	    buf[0] = '\0';
    37	    while (len + 1 < cap) {
    38	        ssize_t n = read(fd, buf + len, cap - 1 - len);
    39	        if (n < 0) {
    40	            if (errno == EINTR)
    41	                continue;
    42	            buf[len] = '\0';
    43	            return -1;
    44	        }
    45	        if (n == 0)
    46	            break;
    47	        len += (size_t)n;
    48	    }
    49	    buf[len] = '\0';
    50	    return (ssize_t)len;
    51	}
    52	
    53	static int run_child(const char *arg, struct result *r)
    54	{
    55	    int po[2], pe[2];
    56	    r->status = -1;
    57	    r->out[0] = r->err[0] = '\0';
    58	    if (pipe(po) != 0)
    59	        return -1;
    60	    if (pipe(pe) != 0) {
    61	        close(po[0]);
    62	        close(po[1]);
    63	        return -1;
    64	    }
    65	    pid_t pid = fork();
    66	    if (pid < 0) {
    67	        close(po[0]); close(po[1]); close(pe[0]); close(pe[1]);
    68	        return -1;
    69	    }
    70	    if (pid == 0) {
    71	        if (dup2(po[1], STDOUT_FILENO) < 0 || dup2(pe[1], STDERR_FILENO) < 0)
    72	            _exit(127);
    73	        close(po[0]); close(po[1]); close(pe[0]); close(pe[1]);
    74	        execl(OPENCHAIR_BIN, OPENCHAIR_BIN, arg, (char *)NULL);
    75	        _exit(127);
    76	    }
    77	    close(po[1]);
    78	    close(pe[1]);
    79	    /* Output is far below pipe capacity, so sequential draining cannot deadlock. */
    80	    int rc = (drain(po[0], r->out, sizeof r->out) < 0 ||
    81	              drain(pe[0], r->err, sizeof r->err) < 0) ? -1 : 0;
    82	    close(po[0]);
    83	    close(pe[0]);
    84	    int st;
    85	    if (waitpid(pid, &st, 0) != pid)
    86	        return -1;
    87	    if (WIFEXITED(st))
    88	        r->status = WEXITSTATUS(st);
    89	    return rc;
    90	}
