   118	static void test_cli_bad_arg(void)
   119	{
   120	    struct result r;
   121	    CHECK(run_child("--bogus", &r) == 0);
   122	    CHECK(r.status == 2);
   123	    CHECK(r.out[0] == '\0');
   124	    CHECK(r.err[0] != '\0');
   125	}
